import java.lang.reflect.Executable;
import java.lang.reflect.Modifier;
import org.apache.commons.lang3.ClassUtils;

private static boolean isMatchingExecutable(final Executable method, final Class<?>[] parameterTypes) {
    if (parameterTypes == null) {
        return method.getParameterCount() == 0;
    }

    final Class<?>[] methodParameterTypes = method.getParameterTypes();

    if (method.isVarArgs()) {
        // Ensure we have enough parameters if the method is varargs
        if (parameterTypes.length < methodParameterTypes.length - 1) {
            return false;
        }

        int i;
        // Check all fixed arguments (non-varargs)
        for (i = 0; i < methodParameterTypes.length - 1; i++) {
            if (!ClassUtils.isAssignable(parameterTypes[i], methodParameterTypes[i], true)) {
                return false;
            }
        }

        // Check varargs
        final Class<?> varArgParameterType = methodParameterTypes[methodParameterTypes.length - 1].getComponentType();
        for (; i < parameterTypes.length; i++) {
            if (!ClassUtils.isAssignable(parameterTypes[i], varArgParameterType, true)) {
                return false;
            }
        }
        return true;
    } else {
        // If not varargs, ensure the lengths match
        if (parameterTypes.length != methodParameterTypes.length) {
            return false;
        }

        // Check each parameter
        for (int i = 0; i < parameterTypes.length; i++) {
            if (!ClassUtils.isAssignable(parameterTypes[i], methodParameterTypes[i], true)) {
                return false;
            }
        }
        return true;
    }
}

